INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(13501, 'Psalms 37:39', 'Psalms', 37, 39, '&nbsp;مالِک خُدائ نېکانو ته خلاصون ورکوى، او هغه په وخت د مصيبت کښې دوئ ته پناه ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13502, 'Psalms 37:40', 'Psalms', 37, 40, '&nbsp;مالِک خُدائ د هغوئ مدد کوى، او د بدعملو نه خلاصون ورکوى، هغه دوئ بچ کوى ځکه چې دوئ د هغۀ نه پناه اخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13503, 'Psalms 38:1', 'Psalms', 38, 1, '&nbsp;اے مالِکه خُدايه، په خپل قهر کښې ما مۀ رټه تۀ په خپله غصه کښې سزا ما ته مۀ راکوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13504, 'Psalms 38:2', 'Psalms', 38, 2, '&nbsp;ځکه چې ستا غشو سورے کړے يم، او په خپل لاس دې وهلے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13505, 'Psalms 38:3', 'Psalms', 38, 3, '&nbsp;ستا د قهر په وجه زما وجود کښې بيمارى ده، زما د ګناه په وجه هډوکى مې مات شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13506, 'Psalms 38:4', 'Psalms', 38, 4, '&nbsp;زما ګناهونه په ما باندې غالب شوى دى، د ګناه دا پنډ د وړلو د برداشت نه بهر شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13507, 'Psalms 38:5', 'Psalms', 38, 5, '&nbsp;پرهرونه مې ټول سخا شول بوئ ترې روان شوے دے، زما د کم عقلتوب په وجه مې ځکه دا حال دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13508, 'Psalms 38:6', 'Psalms', 38, 6, '&nbsp;زۀ کوږ شوے خراب شوے يم، زۀ د درد په وجه ټوله ورځ غمژن يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13509, 'Psalms 38:7', 'Psalms', 38, 7, '&nbsp;او ملا مې د سرې تبې په وجه سوزيږى، او په بدن کښې مې دم نشته ختميږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13510, 'Psalms 38:8', 'Psalms', 38, 8, '&nbsp;زۀ کمزورے شوے بلکل تباه شوے يم، زۀ زبيرګى کوم په زړۀ باندې غمژن يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13511, 'Psalms 38:9', 'Psalms', 38, 9, '&nbsp;اے مالِکه خُدايه، زما ټول ارمانونه ستا په وړاندې ښکاره دى، او زما اسويلى آهونه ستا نه پټ نۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13512, 'Psalms 38:10', 'Psalms', 38, 10, '&nbsp;زړۀ زما درزيږى زما زور په ختمېدو دے، تر دې چې مې نظر د سترګو په ختمېدو دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13513, 'Psalms 38:11', 'Psalms', 38, 11, '&nbsp;د بيمارۍ په وجه زما دوستان او ملګرى زما نه په ډډه ودريږى، تر دې چې خپل خاندان هم رانه لرې لرې کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13514, 'Psalms 38:12', 'Psalms', 38, 12, '&nbsp;دشمنانو راته اېښى دى دامونه هغوئ ما قتلول غواړى، زما د تباهۍ منصوبې جوړوى څوک چې ما ته نقصان رسول غواړى، دوئ ټوله ورځ منصوبې جوړوى راسره دوکه کول غواړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13515, 'Psalms 38:13', 'Psalms', 38, 13, '&nbsp;خو زۀ لکه د يو کُوڼ په شان هيڅ نۀ اورم، او زۀ د يو ګونګا په شان شوے يم څۀ نۀ وايم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13516, 'Psalms 38:14', 'Psalms', 38, 14, '&nbsp;زۀ د يو داسې کس په شان شوے يم چې اورېدے نۀ شى، او په خولۀ باندې هيڅ جواب ورکولے نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13517, 'Psalms 38:15', 'Psalms', 38, 15, '&nbsp;زۀ ستا په طمع يمه، اے مالِکه خُدايه. اے مالِکه خُدايه تۀ جواب راکړه، ما له زما پاکه خُدايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13518, 'Psalms 38:16', 'Psalms', 38, 16, '&nbsp;زۀ تا ته کوم سوال دوئ ما پورې خندا ته مۀ پرېږده کله چې زۀ پرېوځم هغوئ مۀ خوشحالوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13519, 'Psalms 38:17', 'Psalms', 38, 17, '&nbsp;ځکه زۀ غورزېدو ته نزدې شوے يم، او مسلسل دردونو راګېر کړے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13520, 'Psalms 38:18', 'Psalms', 38, 18, '&nbsp;زۀ د خپلو ټولو ګناهونو اقرار کوم، زۀ په خپلو ګناهونو ډېره پښېمانتيا کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13521, 'Psalms 38:19', 'Psalms', 38, 19, '&nbsp;زما دشمنان ډېر او تکړه دى، ډېر دى چې بې‌وجې ما نه نفرت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13522, 'Psalms 38:20', 'Psalms', 38, 20, '&nbsp;د ښو په ځائ دوئ ما سره بد کوى زۀ نېکى کوم په دې وجه هغوئ ما سره بدى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13523, 'Psalms 38:21', 'Psalms', 38, 21, '&nbsp;اے مالِکه خُدايه، ما مۀ پرېږده، اے زما پاکه خُدايه، زما نه لرې مۀ ودرېږه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13524, 'Psalms 38:22', 'Psalms', 38, 22, '&nbsp;زر راشه او زما مدد وکړه، اے مالِکه خُدايه، زما خلاصونکيه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13525, 'Psalms 39:1', 'Psalms', 39, 1, '&nbsp;ما ووئيل چې، ”زۀ به د خپل عمل خيال ساتم نو چې په خپله ژبه ګناه ونۀ کړم، ترڅو چې بدعمله زما د وړاندې وى زۀ به خپله ژبه چپ ساتم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13526, 'Psalms 39:2', 'Psalms', 39, 2, '&nbsp;زۀ خو خاموش ولاړ وم، او هيڅ خبره مې هم نۀ کوله، په دې باندې زما پرېشانى نوره هم زياتېدله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13527, 'Psalms 39:3', 'Psalms', 39, 3, '&nbsp;زما د زړۀ پرېشانى او غم زياتېدلو. ما چې څومره سوچ کولو، نو دومره مې غم زياتېدو، خو آخر هم ما د خپل ځان سره ووئيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13528, 'Psalms 39:4', 'Psalms', 39, 4, '&nbsp;”اے مالِکه خُدايه، زما ژوندون چې څومره دے ما ته راوښايه، چې زما عمر به څومره وى ما ته زما د مرګ نېټه راوښايه، ما ته وښايه چې څومره فانى يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13529, 'Psalms 39:5', 'Psalms', 39, 5, '&nbsp;تا زما د ژوند نه د ژمې مازيګر جوړ کړو، زما ژوند دې په خپل نظر يوه لحظه کړو، د ټولو انسانانو ژوندون صرف هوا ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13530, 'Psalms 39:6', 'Psalms', 39, 6, '&nbsp;هر انسان د سورى په شان په تېزۍ سره د مرګى طرف ته روان وى، دوئ مال راټولوى خو خبر نۀ دى چې دا به څوک خرچ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13531, 'Psalms 39:7', 'Psalms', 39, 7, '&nbsp;خو اوس، اے مالِکه خُدايه، زۀ د څۀ طمع کوم؟ زۀ په تا باندې توکل کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13532, 'Psalms 39:8', 'Psalms', 39, 8, '&nbsp;زما د سرکشۍ نه ما بچ کړه، ما د کم عقلو د خندا مۀ جوړوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13533, 'Psalms 39:9', 'Psalms', 39, 9, '&nbsp;زۀ چپ وم، ما خپله خولۀ بنده کړې وه، ځکه چې هر څۀ تا په خپله کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13534, 'Psalms 39:10', 'Psalms', 39, 10, '&nbsp;خپل عذاب دې ما نه اخوا کړه ډېر کړېدلے يم، زۀ ستا د لاس په وهلو ډېر ضعيفه شوے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13535, 'Psalms 39:11', 'Psalms', 39, 11, '&nbsp;تۀ انسان د هغۀ د ګناه په وجه تنبيه کوې، او څۀ چې دوئ ته قيمتى وى تۀ هغه د دوئ نه لکه وَينو په شان خورې، انسان هيڅ نۀ دے خو بس يوه ساه ده،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13536, 'Psalms 39:12', 'Psalms', 39, 12, '&nbsp;اے مالِکه خُدايه، زما دُعا تۀ واوره، د مدد دپاره زما فرياد واوره، زما اوښکې مۀ نظر انداز کوه. زۀ خو د يوې لحظې مېلمه يم، لکه زما د پلار نيکۀ په شان يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13537, 'Psalms 39:13', 'Psalms', 39, 13, '&nbsp;ما لږ پرېږده چې دوباره خوشحاله شم، د دې نه مخکښې چې لاړ شم او فنا شم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13538, 'Psalms 40:1', 'Psalms', 40, 1, '&nbsp;په صبر ما د مالِک خُدائ انتظار وکړو، او هغۀ زما فرياد واورېدو او ما ته يې پام وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13539, 'Psalms 40:2', 'Psalms', 40, 2, '&nbsp;هغۀ زۀ د هلاکت د کندې نه رابهر کړم، او د لمدو خټو نه يې راوويستم. زما پښې يې په ګټ کېښودې او مضبوط يې ودرولم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13540, 'Psalms 40:3', 'Psalms', 40, 3, '&nbsp;هغۀ زما په ژبه باندې نوې نغمه سازه کړه، او زمونږ د خُدائ پاک د ثناء صِفت حمد يې راکړو، ډېر چې دا ووينى نو هغوئ به وۀ يريږى او په مالِک خُدائ به يقين وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13541, 'Psalms 40:4', 'Psalms', 40, 4, '&nbsp;هغه سړے به بختور وى د چا چې ايمان په مالِک خُدائ وى، څوک چې مغرورانو ته رجوع نۀ کوى، د هغه کبرژنو څوک چې د بُتانو په وجه ګمراه شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13542, 'Psalms 40:5', 'Psalms', 40, 5, '&nbsp;اے مالِکه خُدايه، زما خُدايه، تا زمونږ دپاره ډيرې معجزې کړې دى، تا زمونږ دپاره بې‌حسابه منصوبې جوړې کړې دى. تا سره هيڅ څوک برابر نشته دے زۀ يې شمېرلے نۀ شم ستا عجيبه کارونه خو بې‌شمېره دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13543, 'Psalms 40:6', 'Psalms', 40, 6, '&nbsp;تۀ خو د چا نه قربانۍ او نذرانې نۀ غواړې، تا زۀ په دې خبره باندې پوهه کړم، د هيچا نه هم سوزېدونکې يا د ګناه نذرانې نۀ غواړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13544, 'Psalms 40:7', 'Psalms', 40, 7, '&nbsp;ما درته ووئيل چې، ”ګوره زۀ حاضر يم، لکه څنګه چې په تورات کښې ليکلے شوى دى نو هغه وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13545, 'Psalms 40:8', 'Psalms', 40, 8, '&nbsp;پاکه خُدايه، چې زۀ ستا رضا پوره کړم، ستا قانون زما په زړۀ کښې ليکلے شوے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13546, 'Psalms 40:9', 'Psalms', 40, 9, '&nbsp;ما ستا د خلاصون زېرے په لوئ جماعت کښې بيان کړو، مالِکه خُدايه تۀ ښۀ خبر يې چې ما خپل بيان بند نۀ کړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13547, 'Psalms 40:10', 'Psalms', 40, 10, '&nbsp;ما په زړۀ کښې ستا د خلاصون خبره پټه نۀ کړه، هر ځائ کښې مې ستا د وفادارۍ او خلاصون خبره وکړه. ما ستا د ابدى مينې او وفادارۍ خبره په لوئ جماعت کښې وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13548, 'Psalms 40:11', 'Psalms', 40, 11, '&nbsp;مالِکه خُدايه، خپله مهربانى به په ما نۀ بندوې، ستا وفادارى او ابدى مينه به همېشه ما بچ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13549, 'Psalms 40:12', 'Psalms', 40, 12, '&nbsp;خو زۀ ډېرو مصيبتونو راګېر کړے يم، لار رانه خطا شوه په ګناهونو کښې ډوب شوے يم، ګناهونه مې د سر وېښتو نه ډېر دى بې‌وسه شوے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13550, 'Psalms 40:13', 'Psalms', 40, 13, '&nbsp;ما بچ کړه، مالِکه خُدايه، د مدد دپاره زر راشه، اے مالِکه خُدايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13551, 'Psalms 40:14', 'Psalms', 40, 14, '&nbsp;څوک چې په کوشش زما د ژوند د ختمولو شى هغوئ دې وشرميږى او وارخطايۍ سره دې مخ شى، څوک چې په نېت زما د خرابولو شى هغوئ ټول دې ناکامه او شرمنده شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13552, 'Psalms 40:15', 'Psalms', 40, 15, '&nbsp;هغوئ دې ټول په شرم وشرميږى، څوک چې راپورې خندا کوى او ما پورې لګيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13553, 'Psalms 40:16', 'Psalms', 40, 16, '&nbsp;څوک چې ستا په لټون شى هغوئ دې ټول تا سره خوشحاله شى، څوک چې ستا خلاصون سره مينه کوى او دوئ دې تل دا وائى چې، ”مالِک خُدائ لوئ دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13554, 'Psalms 40:17', 'Psalms', 40, 17, '&nbsp;بيا هم زۀ غريب او حاجتمند يم، زۀ دې د مالِک خُدائ په نظر يم. زما مددګار او خلاصوونکيه، زر راشه، اے پاکه خُدايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13555, 'Psalms 41:1', 'Psalms', 41, 1, '&nbsp;بختور دے هغه څوک چې د مسکينانو خيال ساتى، کله چې دے په تکليف کښې وى مالِک خُدائ ورله خلاصون ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13556, 'Psalms 41:2', 'Psalms', 41, 2, '&nbsp;مالِک خُدائ به د هغۀ حفاظت کوى او ژوند به يې په امان کښې ساتى، هغه به په دُنيا کښې ورله برکت ورکړى او د دشمنانو د لاس نه به يې ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13557, 'Psalms 41:3', 'Psalms', 41, 3, '&nbsp;مالِک خُدائ به يې په بيمارۍ کښې خيال ساتى او هغه به يې د بيمارۍ د کټ نه روغ رمټ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13558, 'Psalms 41:4', 'Psalms', 41, 4, '&nbsp;ما ووئيل چې، ”اے مالِکه خُدايه، په ما رحم وکړه ما له شفا راکړه، ځکه چې ما ستا خلاف ګناه کړې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13559, 'Psalms 41:5', 'Psalms', 41, 5, '&nbsp;زما دشمنان په بدنېتۍ سره داسې وائى چې، ”کله به دے مړ شى، او نوم به يې څومره زر د زمکې مخ نه ورک شى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13560, 'Psalms 41:6', 'Psalms', 41, 6, '&nbsp;هغوئ چې کله زما ليدو له راځى نو فضول خبرې کوى، او دروغ وائى او په زړۀ کښې شرارت راجمع کوى، او چې کله بهر ځى نو په هر ځائ کښې زما غېبت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13561, 'Psalms 41:7', 'Psalms', 41, 7, '&nbsp;زما دشمنان ټول زما خلاف خبرې کوى، هغوئ زما خلاف بد سوچونه کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13562, 'Psalms 41:8', 'Psalms', 41, 8, '&nbsp;او دوئ وائى چې، ”په سخت رنځ پروت دے او د بيا پاڅېدو امکان يې د ‎دې رنځ نه نشته دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13563, 'Psalms 41:9', 'Psalms', 41, 9, '&nbsp;تر دې چې زما نزدې دوست په چا باندې چې ما پوره يقين کولو، نو هغه چا چې روټۍ به يې ما سره خوړه هغه هم زما خلاف شولو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13564, 'Psalms 41:10', 'Psalms', 41, 10, '&nbsp;خو تۀ، اے مالِکه خُدايه، په ما رحم وکړه، چې د هغوئ نه خپله بدله واخلم، ما دوباره روغ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13565, 'Psalms 41:11', 'Psalms', 41, 11, '&nbsp;چې تۀ رانه رضا يې زۀ په دې پوهېږم، تا زۀ د دشمنانو لاسونو ته پرې نۀ ښودم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13566, 'Psalms 41:12', 'Psalms', 41, 12, '&nbsp;تا زۀ زما د تقوىٰ په وجه اوچت کړم، او د تل دپاره دې په خپل حضور کښې وساتلم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13567, 'Psalms 41:13', 'Psalms', 41, 13, '&nbsp;مبارک دې وى مالِک، د بنى اِسرائيلو خُدائ، د ازل نه تر ابده آمين، آمين.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13568, 'Psalms 42:1', 'Psalms', 42, 1, '&nbsp;څنګه چې هوسۍ د نِهر اوبو پسې تلوسه کوى، داسې خُدايه پاکه، زړۀ مې تا پسې تلوسه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13569, 'Psalms 42:2', 'Psalms', 42, 2, '&nbsp;زما زړۀ د خُدائ پاک تږے دے، زۀ د ژوندى خُدائ پاک تږے يم. زۀ به کله لاړ شم چې د هغۀ حضور کښې ودرېږم؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13570, 'Psalms 42:3', 'Psalms', 42, 3, '&nbsp;اوښکې مې خوراک دى شپه او ورځ زۀ ژړېږم، هر وخت راته خلق لګيا وى، ”ووايه، ستا خُدائ چرته دے؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13571, 'Psalms 42:4', 'Psalms', 42, 4, '&nbsp;تېر وخت چې راپه ياد شى په زړۀ باندې غمژن شم، چې څنګه ډېرو خلقو سره به زۀ د خُدائ کور ته تلم، او هغوئ به مې د خُدائ پاک عبادتګاه ته په خپله مشرۍ کښې بوتلل، نو په لويه ډله کښې به ما په تېزه د هغوئ سره د خوشحالۍ په آواز د شُکر ګزارۍ ثنا وئيله،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13572, 'Psalms 42:5', 'Psalms', 42, 5, '&nbsp;ولې خفه کېږې زما روحه؟ دومره ولې پرېشانه کېږې تۀ؟ په خُدائ پاک باندې توکل کوه مۀ پرېشانه کېږه تۀ، زۀ به بيا ستا ثناء صِفت بيان کړم، پاکه خُدايه ځکه چې هم تا زۀ خلاص کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13573, 'Psalms 42:6', 'Psalms', 42, 6, '&nbsp;زړۀ مې پرېشانه دے نو ځکه زۀ تا يادوم، د اُردن لرى مُلک او د حرمون او د مِضار د اوچت غرونو نه زۀ تا يادوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13574, 'Psalms 42:7', 'Psalms', 42, 7, '&nbsp;ستا د ژورو سمندرونو او ابشارونو شور زۀ اورم، موجونو او چپو د سمندر زۀ ډوب کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13575, 'Psalms 42:8', 'Psalms', 42, 8, '&nbsp;مالِک خُدائ د ورځې خپله ابدى مينه په ما راوروى، د هغۀ حمد په شپه کښې زما زړۀ کښې وى، دُعا کوم هغه خُدائ پاک ته چې څوک ژوند راکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13576, 'Psalms 42:9', 'Psalms', 42, 9, '&nbsp;څوک چې زما مضبوط ګټ دے، زۀ به خُدائ پاک ته داسې ووايم، ”ولې دې هېر کړے يم زما دشمنان په ما دومره ظلم ولې کوى چې زۀ غمژن ګرځم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13577, 'Psalms 42:10', 'Psalms', 42, 10, '&nbsp;د دشمن پېغور هډوکى مات کړل ما له هر وخت راته لګيا وى دشمنان زما چې، ”ووايه اوس چرته دے خُدائ پاک ستا؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13578, 'Psalms 42:11', 'Psalms', 42, 11, '&nbsp;ولې خفه کېږې زما روحه، دومره ولې پرېشانه کېږې تۀ؟ په خُدائ پاک باندې توکل کوه مۀ پرېشانه کېږه تۀ، زۀ به بيا ستا ثناء صِفت بيان کړم، خُدايه ځکه چې هم تا زۀ خلاص کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13579, 'Psalms 43:1', 'Psalms', 43, 1, '&nbsp;اے پاکه خُدايه، ما بې‌ګناه وګرځوه، د بې‌ايمانه خلقو په خلاف زما په حق کښې فېصله واوروه، خو تۀ ما ته د بدکارانو او ټګمارانو نه خلاصون راکوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13580, 'Psalms 43:2', 'Psalms', 43, 2, '&nbsp;تۀ زما خُدائ پاک او زما قلعه يې، ولې دې رد کړے يم؟ نو ولې غمژن ګرځم دشمن راباندې ظلم کوى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13581, 'Psalms 43:3', 'Psalms', 43, 3, '&nbsp;خپل نُور او خپل حقيقت دې نازل کړه، چې ما ته لارښودنه وکړى، او ما دې هغه مقدس غر ته بوځى کوم ځائ چې تۀ اوسېږې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13582, 'Psalms 43:4', 'Psalms', 43, 4, '&nbsp;زۀ به د خُدائ پاک قربان‌ګاه ته ورشم، هغه خُدائ د چا نه چې ډېر خوشحال شم، زۀ به د رباب په نغمو کښې ستا ثناء صِفت وکړم، اے خُدايه، زما پاکه خُدايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13583, 'Psalms 43:5', 'Psalms', 43, 5, '&nbsp;ولې خفه کېږې زما روحه، دومره ولې پرېشانه کېږې تۀ؟ په خُدائ پاک باندې توکل کوه مۀ پرېشانه کېږه تۀ، زۀ به بيا ستا ثناء صِفت بيان کړم، پاکه خُدايه، ځکه چې هم تا زۀ خلاص کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13584, 'Psalms 44:1', 'Psalms', 44, 1, '&nbsp;اے پاکه خُدايه، مونږ په خپلو غوږونو اورېدلې دى، زمونږ پلار نيکۀ هر هغه څۀ مونږ ته بيان کړى دى، کوم کارونه چې تا د هغوئ په زمانه يعنې پخوا زمانه کښې د هغوئ دپاره کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13585, 'Psalms 44:2', 'Psalms', 44, 2, '&nbsp;تا په خپل طاقت سره هغه قومونه وويستل، او زمونږ پلار نيکۀ دې ودان کړل، هغه خلق دې تباه کړل، زمونږ پلار نيکۀ دې آزاد کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13586, 'Psalms 44:3', 'Psalms', 44, 3, '&nbsp;خو دا زمکه هغوئ په خپله تُوره نۀ وه ګټلې، او نۀ د هغوئ لاسونو ورته کاميابى ورکړې، دا خو ستا د ښى لاس، او ستا د مټ او ستا د مخ رڼا وه، ځکه چې تا هغوئ سره مينه کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13587, 'Psalms 44:4', 'Psalms', 44, 4, '&nbsp;تۀ يې زما بادشاه او پاک خُدائ زما، چا چې د يعقوب اولاد له لويه کاميابى ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13588, 'Psalms 44:5', 'Psalms', 44, 5, '&nbsp;ستا په زور مونږ خپل دشمنان په شا کړل، او ستا په نوم مونږ خپل دشمنان د پښو لاندې کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13589, 'Psalms 44:6', 'Psalms', 44, 6, '&nbsp;زۀ په خپله لينده باندې يقين نۀ ساتم، نۀ په خپله تُوره د خلاصون يقين ساتم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13590, 'Psalms 44:7', 'Psalms', 44, 7, '&nbsp;تا مونږ ته په خپلو دشمنانو فتح راکړه، تا زمونږ مخالفين شرمنده کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13591, 'Psalms 44:8', 'Psalms', 44, 8, '&nbsp;مونږ ټوله ورځ په خُدائ پاک باندې فخر کوُو، مونږ به تل ستا د نوم حمد و ثناء کوُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13592, 'Psalms 44:9', 'Psalms', 44, 9, '&nbsp;خو اوس تا مونږه رد او رسوا کړُو، تلل دې زمونږ د لښکرو سره بند کړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13593, 'Psalms 44:10', 'Psalms', 44, 10, '&nbsp;تا مونږ د دشمنانو په وړاندې په شا کړُو، او زمونږ دشمنانو مونږ لوټ کړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13594, 'Psalms 44:11', 'Psalms', 44, 11, '&nbsp;مونږ تا د ګډو په شان حلالېدو ته پرېښودو، او د قومونو په مينځ کښې دې تس نس کړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13595, 'Psalms 44:12', 'Psalms', 44, 12, '&nbsp;تا خپل خلق په کم قيمت خرڅ کړل، او د هغوئ په خرڅولو کښې دې هيڅ ګټه ونۀ کړله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13596, 'Psalms 44:13', 'Psalms', 44, 13, '&nbsp;تا مونږ د خپلو ګاوڼديانو د خندا کړلو، تا مونږ د ګېرچاپېره خلقو د ټوقو او مسخرو کړلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13597, 'Psalms 44:14', 'Psalms', 44, 14, '&nbsp;تا مونږ نه په قومونو کښې د دوئ د ټوقو ګوډاګى جوړ کړل، او دوئ مونږ پورې خپل سرونه د نفرت په وجه خوځول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13598, 'Psalms 44:15', 'Psalms', 44, 15, '&nbsp;زۀ ټوله ورځ بې‌عزته کېږم، او په مخ مې شرم راخور شوے زۀ شرمېږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13599, 'Psalms 44:16', 'Psalms', 44, 16, '&nbsp;ځکه چې خلق راپورې ټوقې مسخرې کوى، او زما دشمنان رانه د بدل اخستو کوشش کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13600, 'Psalms 44:17', 'Psalms', 44, 17, '&nbsp;دا هر څۀ چې مونږ سره وشول خو بيا هم مونږ تۀ هېر نۀ کړې، هغه مو نۀ دے مات کړے کوم لوظ چې تا مونږ سره کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');